Question:
定义一个数组的极差为：数组的元素最大值减去最小值。

小红拿到了一个数组，她准备进行恰好一次操作：选择一个非空区间，将其中所有元素都乘以 2。

小红希望最小化数组的极差，你能帮帮她吗？


Description:
题目：数值膨胀之美

定义一个数组的极差为：数组的元素最大值减去最小值。

小红拿到了一个数组，她准备进行恰好一次操作：选择一个非空区间，将其中所有元素都乘以 2。

小红希望最小化数组的极差，你能帮帮她吗？


Student Program:
[Program Segment 1/2]
#include<bits/stdc++.h>
#define int long long
const int M = 2e5 + 7;

signed main () {
	std::ios::sync_with_stdio(false);
	std::cin.tie(nullptr),std::cout.tie(nullptr);
	int n; std::cin >> n;
	std::vector<int> a(n + 1 , 0) , b(n + 1, 0) , Min_pre(n + 1 , INT_MAX) , Min_suf(n + 2 , INT_MAX);
	int l = INT_MAX , r = 1 , Max = 0;
	std::map<int , int > L , R;
	for(int i = 1; i <= n; ++ i) std::cin >> a[i] , R[a[i]] = i , b[i] = a[i] , Max = std::max(Max , a[i]);
	for(int i = 1; i <= n; ++ i) Min_pre[i] = std::min(Min_pre[i - 1] , a[i]);
	for(int i = n; i; -- i) Min_suf[i] = std::min(Min_suf[i + 1] , a[i]);
	for(int i = n; i ; -- i) L[a[i]] = i;
	std::sort(a.begin() + 1 , a.end());
	int cnt = std::unique(a.begin() + 1 , a.end()) - a.begin() - 1;
	int ans = INT_MAX;
	l = L[a[1]] , r = L[a[1]] - 1;
	for(int i = 1; i <= cnt; ++ i) {
		int ql = std::min(L[a[i]] , l);
		int qr = std::max(R[a[i]] , r);
//		std::cerr << ql << ' ' << qr << '\n';
		while(l > ql) {
			l --;
			Max = std::max(Max , b[l] * 2);
		}
		while(r < qr) {
			r ++;
			Max = std::max(b[r] * 2 , Max);
		}
		int Min = std::min({Min_pre[l - 1] , Min_suf[r + 1] , a[1] * 2});
		ans = std::min(Max - Min , ans);
	}


