#include<bits/stdc++.h>
#define int long long
struct T{int l , r , id;};
const int M = 2e5 +7;
T a[M];
int ans[M];
signed main () {
	std::ios::sync_with_stdio(false);
	std::cin.tie(nullptr),std::cout.tie(nullptr);
	int n; std::cin >> n;

	for(int i = 1 , l ,r; i <= n; ++ i) std::cin >> l >> r , a[i] = {l , r , i};
	std::sort(a + 1 , a + 1 + n , [](T a , T b) {
		return a.l < b.l ? a.l < b.l : a.r < b.r;
	});
	int l = 1;
	for(int i = 1; i <= n; ++ i) {
		if(l >= a[i].l && l <= a[i].r) 	ans[a[i].id] = l ,l ++;
	}
	if(l > n) {
		for(int i = 1; i <= n; ++ i) std::cout << ans[i] << ' ';
	}
	else std::cout << -1;

}


