#define PI  std::pair<int , int>
#define fi first
#define se second
#define pb push_back
const int M = 1e2 + 7;
int a[M][M];
void solve() {
	int n; std::cin >> n;
	int cnti = 1 , cntj = 1;
	for(int i = 1; i <= n; ++ i) {
		std::string s; std::cin >> s;
		s = " " + s;
		for(int j = 1; j <= n; ++ j) a[i][j] = s[j] - '0';
	}
	std::vector<PI> ans;
	for(int i = 1; i <= n; ++ i) {
		for(int j = 1; j <= n ;++ j) {
			while(a[i][j]) {
				for(int k = i; k > cnti; -- k) ans.pb({k , j}) , ans.pb({k - 1 , j}) , std::swap(a[k][j] , a[k - 1][j]);
				for(int k = j; k > cntj; -- k) ans.pb({cnti , k}) , ans.pb({cnti , k - 1}) , std::swap(a[cnti][k] , a[cnti][k - 1]);
				cntj ++;
				if(cntj > n / 2) cntj = 1 , cnti ++;
			}
		}
	}
	int m = ans.size();
	assert(m <= n * n * n / 2);
