#include<bits/stdc++.h>
#define int long long
#define pb push_back
#define PI std::pair<int,int>
#define fi first
#define se second
const int M = 2e5 + 7 , mod = 1e9 + 7;
int L[M] , R[M];
int Pow(int a , int b = mod - 2) {
	int ans = 1;
	for(; b; b >>= 1 , (a *= a ) %= mod) if(b & 1) (ans *= a) %= mod;
	return ans;
}
int solve(int a , int b) {
	if(a <= 0 || b <= 0) return 0;
	if(a < b) std::swap(a , b);
	int tmp1 = (a - b) * a % mod * b % mod * Pow(2) % mod;
//	int tmp2 = b * (b - 1) % mod * (b + 1) % mod * Pow(3) % mod;
	int tmp2 = (((b * b % mod * b % mod + 4 * b % mod * b % mod - 4 * b) % mod + mod) % mod) * Pow(8) % mod;
	if(b & 1) (tmp2 += Pow(8) * ((b * b % mod + 2 * b % mod) % mod) % mod) %= mod;
	return (tmp1 + tmp2) % mod;
}
int query(int i , int j) {
	return ((solve(R[i] , R[j]) + solve(L[i] - 1 , L[j] - 1) - solve(L[i] - 1 , R[j]) - solve(R[i] , L[j] - 1)) % mod + mod) % mod;
}
void solve() {
	int n; std::cin >> n;
	for(int i = 1; i <= n; ++ i) std::cin >> L[i] >> R[i];
	int ans = 0;
	for(int i = 2; i <= n; ++ i) {
		(ans += query(i , i - 1) * Pow((R[i] - L[i] + 1) * (R[i - 1] - L[i - 1] + 1)) % mod) %= mod;
	}
	std::cout << ans << '\n';
}

