bool bfs(int n, int m) {
    std::queue<int> q;
    std::map<int , int> f;
    q.push(n);
	f[n] = 1;
    while (!q.empty()) {
        int x = q.front(); q.pop();
        if (x == m) return 1;
        if (x <= 4 * m && f[x * 2] == 0) f[x * 2] = 1 , q.push(x * 2);
        int y = std::sqrt(x);
        if (f[y] == 0) f[y] = 1 , q.push(y);
    }
    return 0;
}

