const int M = 1e5 + 7;
int root[M] , cnt[M * 30] , T , ls[M * 30] , rs[M * 30] , a[M];
void modify(int &rt1 , int &rt2 , int l , int r , int p) {
	rt1 = ++ T , ls[rt1] = ls[rt2] , rs[rt1] = rs[rt2] , cnt[rt1] = cnt[rt2] + 1;
	if(l == r) return ; int mid = l + r >> 1;
	if(p <= mid) modify(ls[rt1] , ls[rt2] , l , mid , p);
	else modify(rs[rt1] , rs[rt2] , mid + 1 , r , p);
}
int query(int rt1 , int rt2 , int l , int r , int L , int R) {
	if(L <= l && R >= r) return cnt[rt2] - cnt[rt1];
	int mid = l + r >> 1;
	int ans = 0;
	if(L <= mid) ans += query(ls[rt1] , ls[rt2] , l , mid , L , R);
	if(R > mid) ans += query(rs[rt1] , rs[rt2] , mid + 1 , r , L , R);
	return ans;
}
void solve() {
	int n , m; std::cin >> n >> m;
	for(int i = 1; i <= n; ++ i) std::cin >> a[i] ,  modify(root[i] , root[i - 1] , 1 , n , a[i]);
	for(int i = 1; i <= m; ++ i) {
		int l , r , k; std::cin >> l >> r >> k;
		std::cout << l + query(root[l - 1] , root[r] , 1 , n , 1 , a[k] - 1) << '\n';
	}
}

